class View:
    def __init__(self):
        self.rows=[]
        self.notes={}
        self.loading=False
        self.error=None
        self.seq=0
        self.current_request_id=None
        self._has_finished=False

    def begin(self, query):
        # monotonically increasing request id
        self.seq += 1
        rid = self.seq
        self.current_request_id = rid
        self.loading = False
        self.error = None
        # keep existing rows and notes
        return rid

    def finish(self, request_id, rows):
        # only the latest begun request can update rows, once
        if request_id != self.current_request_id:
            return False
        if self._has_finished:
            return False
        self._has_finished = True
        self.current_request_id = None
        self.rows = rows  # update rows with the valid finish
        return True

    def get_loading(self):
        return self.loading

    def copy_accepted_rows(self):
        # copy accepted rows (the current rows)
        return list(self.rows)
